import{c as a,Q as s,j as t,m as o}from"./chunks/framework.rWdQudnF.js";const m=JSON.parse('{"title":"信息系统架构","description":"","frontmatter":{"title":"信息系统架构"},"headers":[],"relativePath":"架构师 在线刷题/51CT0题库 章节练习/信息系统架构设计理论与实践（第二版）/信息系统架构.md","filePath":"架构师 在线刷题/51CT0题库 章节练习/信息系统架构设计理论与实践（第二版）/信息系统架构.md","lastUpdated":null}'),i={name:"架构师 在线刷题/51CT0题库 章节练习/信息系统架构设计理论与实践（第二版）/信息系统架构.md"};function n(r,l,c,e,u,d){return s(),t("div",null,[...l[0]||(l[0]=[o('<h1 id="信息系统架构" tabindex="-1">信息系统架构 <a class="header-anchor" href="#信息系统架构" aria-label="Permalink to &quot;信息系统架构&quot;">​</a></h1><blockquote><p>共 13 题 · 题型：单选题 · 来源：51CTO题库</p></blockquote><h2 id="q1-系统应用架构设计中-网络架构数据流图的主要作用是将处理器和设备分配到网络中。-不属于网络架构数据流图的内容。" tabindex="-1">Q1. 系统应用架构设计中，网络架构数据流图的主要作用是将处理器和设备分配到网络中。（ ）不属于网络架构数据流图的内容。 <a class="header-anchor" href="#q1-系统应用架构设计中-网络架构数据流图的主要作用是将处理器和设备分配到网络中。-不属于网络架构数据流图的内容。" aria-label="Permalink to &quot;Q1. 系统应用架构设计中，网络架构数据流图的主要作用是将处理器和设备分配到网络中。（ ）不属于网络架构数据流图的内容。&quot;">​</a></h2><ul><li><strong>A.</strong> 服务器、客户端及其物理位置</li><li><strong>B.</strong> 处理器说明信息</li><li><strong>C.</strong> 单位时间的数据流大小</li><li><strong>D.</strong> 传输协议</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>C</strong></p></div></details><h2 id="q2-企业信息基础设施包括哪三个部分-。" tabindex="-1">Q2. 企业信息基础设施包括哪三个部分（ ）。 <a class="header-anchor" href="#q2-企业信息基础设施包括哪三个部分-。" aria-label="Permalink to &quot;Q2. 企业信息基础设施包括哪三个部分（ ）。&quot;">​</a></h2><ul><li><strong>A.</strong> 技术基础设施、信息资源设施和人力资源设施</li><li><strong>B.</strong> 技术基础设施、信息资源设施和管理基础设施</li><li><strong>C.</strong> 硬件基础设施、软件基础设施和管理基础设施</li><li><strong>D.</strong> 网络基础设施、数据基础设施和应用基础设施</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>B</strong></p></div></details><h2 id="q3-在企业信息系统总体框架中-战略系统的组成部分不包括以下哪项-。" tabindex="-1">Q3. 在企业信息系统总体框架中，战略系统的组成部分不包括以下哪项（ ）。 <a class="header-anchor" href="#q3-在企业信息系统总体框架中-战略系统的组成部分不包括以下哪项-。" aria-label="Permalink to &quot;Q3. 在企业信息系统总体框架中，战略系统的组成部分不包括以下哪项（ ）。&quot;">​</a></h2><ul><li><strong>A.</strong> 高层决策支持系统</li><li><strong>B.</strong> 企业战略规划体系</li><li><strong>C.</strong> 业务流程管理系统</li><li><strong>D.</strong> 信息系统对高层决策的支持能力</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>C</strong></p></div></details><h2 id="q4-某公司正在规划其企业信息系统的总体框架-以下哪个选项不属于企业信息系统总体框架的四个主要组成部分-。" tabindex="-1">Q4. 某公司正在规划其企业信息系统的总体框架，以下哪个选项不属于企业信息系统总体框架的四个主要组成部分（ ）。 <a class="header-anchor" href="#q4-某公司正在规划其企业信息系统的总体框架-以下哪个选项不属于企业信息系统总体框架的四个主要组成部分-。" aria-label="Permalink to &quot;Q4. 某公司正在规划其企业信息系统的总体框架，以下哪个选项不属于企业信息系统总体框架的四个主要组成部分（ ）。&quot;">​</a></h2><ul><li><strong>A.</strong> 战略系统</li><li><strong>B.</strong> 业务系统</li><li><strong>C.</strong> 人力资源系统</li><li><strong>D.</strong> 信息基础设施</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>C</strong></p></div></details><h2 id="q5-在面向服务的架构-soa-中-以下哪个特征最能体现其核心设计理念-。" tabindex="-1">Q5. 在面向服务的架构（SOA）中，以下哪个特征最能体现其核心设计理念（ ）。 <a class="header-anchor" href="#q5-在面向服务的架构-soa-中-以下哪个特征最能体现其核心设计理念-。" aria-label="Permalink to &quot;Q5. 在面向服务的架构（SOA）中，以下哪个特征最能体现其核心设计理念（ ）。&quot;">​</a></h2><ul><li><strong>A.</strong> 集中式的功能实现</li><li><strong>B.</strong> 紧密耦合的系统组件</li><li><strong>C.</strong> 独立服务的定义和松散耦合</li><li><strong>D.</strong> 单一的企业服务总线</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>C</strong></p></div></details><h2 id="q6-在客户机-服务器模式中-以下哪种结构不属于三层c-s或b-s架构-。" tabindex="-1">Q6. 在客户机/服务器模式中，以下哪种结构不属于三层C/S或B/S架构（ ）。 <a class="header-anchor" href="#q6-在客户机-服务器模式中-以下哪种结构不属于三层c-s或b-s架构-。" aria-label="Permalink to &quot;Q6. 在客户机/服务器模式中，以下哪种结构不属于三层C/S或B/S架构（ ）。&quot;">​</a></h2><ul><li><strong>A.</strong> Web浏览器 + Web服务器 + 后台数据库</li><li><strong>B.</strong> 前台客户端 + 后台服务端 + 后台数据库</li><li><strong>C.</strong> 前台客户端 + 后台数据库</li><li><strong>D.</strong> Web浏览器 + 应用服务器 + 数据库服务器</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>C</strong></p></div></details><h2 id="q7-在企业应用集成中-哪种架构模型最适合实现不同异构系统之间的松耦合集成-。" tabindex="-1">Q7. 在企业应用集成中，哪种架构模型最适合实现不同异构系统之间的松耦合集成（ ）。 <a class="header-anchor" href="#q7-在企业应用集成中-哪种架构模型最适合实现不同异构系统之间的松耦合集成-。" aria-label="Permalink to &quot;Q7. 在企业应用集成中，哪种架构模型最适合实现不同异构系统之间的松耦合集成（ ）。&quot;">​</a></h2><ul><li><strong>A.</strong> 单机应用系统</li><li><strong>B.</strong> 两层C/S架构</li><li><strong>C.</strong> MVC结构</li><li><strong>D.</strong> 面向服务的架构SOA</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>D</strong></p></div></details><h2 id="q8-根据信息系统的物理结构分类-以下哪种结构的优点是资源集中-便于管理-资源利用率较高-。" tabindex="-1">Q8. 根据信息系统的物理结构分类，以下哪种结构的优点是资源集中，便于管理，资源利用率较高（ ）。 <a class="header-anchor" href="#q8-根据信息系统的物理结构分类-以下哪种结构的优点是资源集中-便于管理-资源利用率较高-。" aria-label="Permalink to &quot;Q8. 根据信息系统的物理结构分类，以下哪种结构的优点是资源集中，便于管理，资源利用率较高（ ）。&quot;">​</a></h2><ul><li><strong>A.</strong> 分布式结构</li><li><strong>B.</strong> 集中式结构</li><li><strong>C.</strong> 网络式结构</li><li><strong>D.</strong> 层次式结构</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>B</strong></p></div></details><h2 id="q9-信息系统的逻辑结构主要体现为什么-。" tabindex="-1">Q9. 信息系统的逻辑结构主要体现为什么（ ）。 <a class="header-anchor" href="#q9-信息系统的逻辑结构主要体现为什么-。" aria-label="Permalink to &quot;Q9. 信息系统的逻辑结构主要体现为什么（ ）。&quot;">​</a></h2><ul><li><strong>A.</strong> 硬件系统的空间分布</li><li><strong>B.</strong> 功能综合体和概念性框架</li><li><strong>C.</strong> 物理资源的集中配置</li><li><strong>D.</strong> 网络拓扑结构</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>B</strong></p></div></details><h2 id="q10-信息系统架构可以分为哪两种基本类型-。" tabindex="-1">Q10. 信息系统架构可以分为哪两种基本类型（ ）。 <a class="header-anchor" href="#q10-信息系统架构可以分为哪两种基本类型-。" aria-label="Permalink to &quot;Q10. 信息系统架构可以分为哪两种基本类型（ ）。&quot;">​</a></h2><ul><li><strong>A.</strong> 硬件结构和软件结构</li><li><strong>B.</strong> 物理结构和逻辑结构</li><li><strong>C.</strong> 集中式结构和分布式结构</li><li><strong>D.</strong> 功能结构和数据结构</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>B</strong></p></div></details><h2 id="q11-问题1-6分-java企业级应用框架一般被划分为3个层次-请用150字以内的文字说明都有哪3个层次-功能分别是什么" tabindex="-1">Q11. [问题1]（6分） Java企业级应用框架一般被划分为3个层次，请用150字以内的文字说明都有哪3个层次?功能分别是什么? <a class="header-anchor" href="#q11-问题1-6分-java企业级应用框架一般被划分为3个层次-请用150字以内的文字说明都有哪3个层次-功能分别是什么" aria-label="Permalink to &quot;Q11. [问题1]（6分） Java企业级应用框架一般被划分为3个层次，请用150字以内的文字说明都有哪3个层次?功能分别是什么?&quot;">​</a></h2><details class="callout callout-info"><summary class="callout-title"><span class="callout-icon">ℹ️</span>材料</summary><div class="callout-body"><p>试题五（25分）阅读以下关于Java企业级应用系统开发架构的叙述，根据要求回答问题。[说明] 某软件公司承担了某中小型企业应用软件开发任务，进度要求紧迫。为了按时完成任务，选择合适的企业应用系统开发架构非常重要。项目组在进行方案论证时，项目组成员提出了两种开发思路。 刘工建议采用J2EE 5.0和EJB 3.0进行开发。理由是J2EE定义了标准的应用开发体系结构和部署环境，EJB是J2EE的基础和核心。J2EE 5.0主要目标是简化开发，相比EJB 2.1，EJB 3.0具有很多改进和提高。 杜工建议采用Struts、Spring和Hibenate轻量级开源框架相结合的方式。理由是随着Java开源项目阵营的发展壮大，一些基于POJOs(Plan Old Java Objects)的开源框架被广泛地引入到Java企业应用开发中来，与重量级的EJB框架相比，这些轻量级的框架有很多优点。 项目组仔细比较分析了两种方案的特点、优点和不足之处。认为杜工和刘工的建议都合理，但是从结合当前项目实际情况出发，最后决定采用杜工的建议。</p></div></details><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>【问题一】（1）表现层。对应视图(View)。用于为从客户端发来的请求服务的对象及其行为，用于展现数据以及负责View组件实现模式、组件在View显示粒度、页面跳转，以及事件触发等功能。（2）业务逻辑组件层。对应控制器(Controller)。用于支持由表现层发起的(某些情况下也可能由持久层直接发起)业务数据的逻辑处理。（3）持久层。实现持久化存储，对应模型(Model)。用于支持外部资源通信。例如，与数据库交互数据等。</p></div></details><h2 id="q12-【问题1】-8分-结合你的系统架构经验-请用400字以内的文字简要讨论c-s和b-s两种架构风格各自的优点和缺点。" tabindex="-1">Q12. 【问题1】（8分）结合你的系统架构经验，请用400字以内的文字简要讨论C/S和B/S两种架构风格各自的优点和缺点。 <a class="header-anchor" href="#q12-【问题1】-8分-结合你的系统架构经验-请用400字以内的文字简要讨论c-s和b-s两种架构风格各自的优点和缺点。" aria-label="Permalink to &quot;Q12. 【问题1】（8分）结合你的系统架构经验，请用400字以内的文字简要讨论C/S和B/S两种架构风格各自的优点和缺点。&quot;">​</a></h2><details class="callout callout-info"><summary class="callout-title"><span class="callout-icon">ℹ️</span>材料</summary><div class="callout-body"><p>试题一（24分）阅读以下关于软件体系结构方面的叙述，根据要求回答下面问题。 [说明] 某大中型企业在全国各城市共有15个左右的分支机构，这些机构已经建设了相关的关系型数据库管理系统，每天负责独立地处理本区域内的业务并实时存储业务数据。PH软件公司承接了该大中型企业信息管理系统的升级改造开发任务。该软件公司的领域专家对需求进行深入分析后，得到的部分系统需求如下。 1、开发一个网络财务程序，使各地员工能在Internet上通过VPN技术进行财务单据报销和处理。 2、为了加强管理，实现对下属分支机构业务数据的异地存储备份，保证数据的安全及恢复，同时对全国业务数据进行挖掘分析，拟在该企业总部建设数据中心。 3、PH公司在设计该财务程序的体系结构时，开发项目组产生了以下分歧： 架构师许工认为应该采用客户机/服务器(C/S)架构风格，各分支机构财务部要安装一个软件客户端，通过这个客户端连接到总公司财务部主机。如果员工在外地出差，需要报销账务的，也需要安装这个客户端才能进行。 架构师郭工认为应该采用浏览器/服务器(B/S)架构风格，各分支机构及出差员工直接通过Windows操作系统自带的IE浏览器就可以连接到总公司的财务部主机。在架构评估会议上，专家对这两种方案进行综合评价，最终采用了C/S和B/S相结合的混合架构风格。</p></div></details><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>C/S架构风格的优点：①客户机应用程序与服务器程序分离，二者的开发既可以分开进行，也可以同时进行；②技术成熟，允许网络分布操作，交互性强，具有安全的存取模式；③网络压力小，响应速度快，有利于处理大量数据；④模型思想简单，易于人们理解和接受等 C/S架构风格的缺点：①客户机与服务器的通信依赖于网络，服务器的负荷过重：②无法实现快速部署和安装，维护工作量大，升级困难；③开发成本较高，客户端程序设计复杂，灵活性差；④用户界面风格不一，软件移植和数据集成困难；⑤数据库的安全性因客户机程序直接访问而降低等 B/S架构风格的优点：①易于部署、维护和升级；②具有良好的开放性和可扩充性，可以应用在广域网上，方便了信息的全球传输、查询和发布；③可跨平台操作，无须开发客户端软件；④通过JDBC等数据库连接接口，提高了动态交互性、服务器的通用性与可移植性等。 B/S架构风格的缺点：①数据的动态交互性不强，不利于在线事务处理(OLTP)应用；②数据查询等响应速度较慢；③系统的安全性较难以控制等。（包括但不限于以上答案）</p></div></details><h2 id="q13-【问题2】-7分-结合你的系统架构经验-请用600字a内的文字简要说明该工程项目采用c-s和b-s相结合的混合架构风格的设计要点及其优点。" tabindex="-1">Q13. 【问题2】（7分）结合你的系统架构经验，请用600字A内的文字简要说明该工程项目采用C/S和B/S相结合的混合架构风格的设计要点及其优点。 <a class="header-anchor" href="#q13-【问题2】-7分-结合你的系统架构经验-请用600字a内的文字简要说明该工程项目采用c-s和b-s相结合的混合架构风格的设计要点及其优点。" aria-label="Permalink to &quot;Q13. 【问题2】（7分）结合你的系统架构经验，请用600字A内的文字简要说明该工程项目采用C/S和B/S相结合的混合架构风格的设计要点及其优点。&quot;">​</a></h2><details class="callout callout-info"><summary class="callout-title"><span class="callout-icon">ℹ️</span>材料</summary><div class="callout-body"><p>试题一（24分）阅读以下关于软件体系结构方面的叙述，根据要求回答下面问题。 [说明] 某大中型企业在全国各城市共有15个左右的分支机构，这些机构已经建设了相关的关系型数据库管理系统，每天负责独立地处理本区域内的业务并实时存储业务数据。PH软件公司承接了该大中型企业信息管理系统的升级改造开发任务。该软件公司的领域专家对需求进行深入分析后，得到的部分系统需求如下。 1、开发一个网络财务程序，使各地员工能在Internet上通过VPN技术进行财务单据报销和处理。 2、为了加强管理，实现对下属分支机构业务数据的异地存储备份，保证数据的安全及恢复，同时对全国业务数据进行挖掘分析，拟在该企业总部建设数据中心。 3、PH公司在设计该财务程序的体系结构时，开发项目组产生了以下分歧： 架构师许工认为应该采用客户机/服务器(C/S)架构风格，各分支机构财务部要安装一个软件客户端，通过这个客户端连接到总公司财务部主机。如果员工在外地出差，需要报销账务的，也需要安装这个客户端才能进行。 架构师郭工认为应该采用浏览器/服务器(B/S)架构风格，各分支机构及出差员工直接通过Windows操作系统自带的IE浏览器就可以连接到总公司的财务部主机。在架构评估会议上，专家对这两种方案进行综合评价，最终采用了C/S和B/S相结合的混合架构风格。</p></div></details><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>(包含但不限于以下内容)。 ①在该企业总部局域网上部署财务Web服务器及其相关的数据库服务器，两种服务器之间采用C/S架构：总部局域网上提供C/S和B/S两种并存的架构风格，根据不同的应用需求和客户需求进行灵活的选择。 ②若项目资金充裕，则在各分支机构局域网中也采用类似于企业总部的部署风格；若项目资金不足，则在各分支机构财务部门局域网中采C/S架构，部署应用服务器及相关的数据库服务器，然后将集中处理的后期财务数据通过VPN技术上传至总部局域网的相应服务器中。 ③在外出差的员工和各分支机构的普通员工通过VPN技术访问企业总部局域网上的Web服务器，查看相关的信息。 采用C/S和B/S混合架构的优点如下(包含但不限于以下内容)： ①充分发挥了B/S与C/S体系结构的优势，弥补了二者的不足。 ②客户请求和信息发布采B/S架构，保持了瘦客户端的优点，客户机只利用浏览器即可完成所有的应用需求。 ③数据库的请求和响应操作采C/S架构，通过在Web应用程序和数据库之间建立ODBC/JDBC连接来完成数据库的连接和请求响应，能完成大量数据的批量录入请求。 ④系统的部署、维护及数据更新方便，不存在完全采用C/S结构带来的客户端维护工作量大等缺点。 ⑤将服务器端划分为Web服务器和Web应用程序两部分。Web应用程序采用组件技术实现三层体系结构中的商业逻辑部分，达到封装源代码、保护知识产权的目的。 ⑥对原基于C/S架构的应用，只需开发用于发布的Web界面，就能升级到这种混合架构系统中，从而最大限度地保护了原有投资。</p></div></details>',41)])])}const p=a(i,[["render",n]]);export{m as __pageData,p as default};
